int main() {
    scanf("%d %d %d", &N, &A, &B);
    int size = 1 << N;

    // Check parity condition: distance must be odd
    int xor = A ^ B;
    int dist = 0;
    for (int i = 0; i < N; i++) {
        if (xor & (1 << i)) dist++;
    }
    if (dist % 2 == 0 && N > 1) {
        printf("NO\n");
        return 0;
    }

    // If N == 1, special case
    if (N == 1) {
        if (A == B) {
            printf("NO\n");
        } else {
            printf("YES\n");
            printf("%d %d\n", A, B);
        }
        return 0;
    }

    // We can construct by starting from a Gray code cycle and rotating/flipping
    // The standard binary-reflected Gray code gives a Hamiltonian cycle.
    // We want to start at A and end at B.

    // Find positions of A and B in the Gray code order
    int posA = -1, posB = -1;
    for (int i = 0; i < size; i++) {
        int val = gray(i);
        if (val == A) posA = i;
        if (val == B) posB = i;
    }

    // We can reverse and shift to make path from A to B
    int *perm = malloc(size * sizeof(int));
    // Try forward direction
    int ok = 0;
    for (int dir = 0; dir < 2; dir++) {
        for (int shift = 0; shift < size; shift++) {
            int start = (posA - shift + size) % size;
            int end = (posB - shift + size) % size;
            if (dir == 1) {
                // reversed direction
                start = (shift - posA + size) % size;
                end = (shift - posB + size) % size;
            }
            int cur = start;
            int step = (dir == 0) ? 1 : -1;
            for (int i = 0; i < size; i++) {
                int idx = (cur + size) % size;
                if (dir == 0)
                    perm[i] = gray(idx);
                else
                    perm[i] = gray((size - 1 - idx + size) % size);
                cur = (cur + step + size) % size;
            }
            if (perm[0] == A && perm[size-1] == B) {
                ok = 1;
                break;
            }
        }
        if (ok) break;
    }

    if (!ok) {
        // fallback: brute force approach for small N (N <= 4) is guaranteed to work if parity matches
        // but our method should always work; if not, just fail.
        printf("NO\n");
        free(perm);
        return 0;
    }

    printf("YES\n");
    for (int i = 0; i < size; i++) {
        if (i) printf(" ");
        printf("%d", perm[i]);
    }
    printf("\n");
    free(perm);
    return 0;
}

