static void build(int n, int a, int b, int *out) {
    if (n == 1) {
        out[0] = a;
        out[1] = b;
        return;
    }

    int x = a ^ b;
    int k = 0;
    while (((x >> k) & 1) == 0) k++;

    int m = 0;
    while (m == k || m == 0) m++;
    // Need some bit different from k. Since n >= 2, such m exists in [0, n-1].

    int a1 = a & ~(1 << k);
    int b1 = (b & ~(1 << k)) >> 1;
    int aa = 0, bb = 0, cc = 0, dd = 0;

    // Remove bit k from a and b to get (n-1)-bit numbers
    aa = (a & ((1 << k) - 1)) | ((a >> 1) & ~((1 << k) - 1));
    bb = aa ^ (1 << m);
    cc = bb ^ 1;
    dd = (b & ((1 << k) - 1)) | ((b >> 1) & ~((1 << k) - 1));

    int half = 1 << (n - 1);
    int *left = (int *)malloc(sizeof(int) * half);
    int *right = (int *)malloc(sizeof(int) * half);

    build(n - 1, aa, bb, left);
    build(n - 1, cc, dd, right);

    for (int i = 0; i < half; i++) {
        int v = left[i];
        out[i] = (v & ((1 << k) - 1)) | ((v & ~((1 << k) - 1)) << 1) | (((a >> k) & 1) << k);
    }
    for (int i = 0; i < half; i++) {
        int v = right[i];
        out[half + i] = (v & ((1 << k) - 1)) | ((v & ~((1 << k) - 1)) << 1) | (((b >> k) & 1) << k);
    }

    free(left);
    free(right);
}

