#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B;
    cin >> N >> A >> B;

    if (__builtin_popcount(A ^ B) % 2 == 0) {
        cout << "NO\n";
        return 0;
    }

    cout << "YES\n";

    // Gray code construction for path from A to B
    vector<int> path;
    path.push_back(A);

    // We'll build recursively: for dimension k, split based on bits
    function<void(int, int, int, int)> build = [&](int l, int r, int start, int end) {
        if (l == r) return;
        int len = r - l + 1;
        int half = len / 2;
        int bit = 31 - __builtin_clz(len);

        // Determine which half start and end belong to
        bool start_in_first = !(start & (1 << bit));
        bool end_in_first = !(end & (1 << bit));

        if (start_in_first && end_in_first) {
            // Both in first half
            build(l, l + half - 1, start, end);
        } else if (!start_in_first && !end_in_first) {
            // Both in second half
            build(l + half, r, start, end);
        } else {
            // Different halves
            // Need a midpoint: flip the bit of start
            int mid = start ^ (1 << bit);
            if (start_in_first) {
                // start in first half, end in second half
                build(l, l + half - 1, start, mid);
                build(l + half, r, mid, end);
            } else {
                build(l + half, r, start, mid);
                build(l, l + half - 1, mid, end);
            }
        }
    };

    // We can generate path by starting from A, building recursively
    vector<int> res;
    function<void(int, int, int)> dfs = [&](int mask, int step, int target) {
        res.push_back(mask);
        if (mask == target) return;
        for (int b = 0; b < N; b++) {
            int nxt = mask ^ (1 << b);
            if (__builtin_popcount(nxt ^ target) < __builtin_popcount(mask ^ target)) {
                dfs(nxt, step + 1, target);
                return;
            }
        }
    };

    // More direct: generate Gray path from A to B
    // We can use a simple recursive path builder
    vector<int> ans;
    function<void(int, int, int)> gray_path = [&](int a, int b, int bits) {
        if (bits == 0) {
            ans.push_back(a);
            return;
        }
        int bit = 1 << (bits - 1);
        if ((a & bit) == (b & bit)) {
            gray_path(a, b, bits - 1);
        } else {
            int mid = a ^ bit;
            gray_path(a, mid, bits - 1);
            gray_path(mid, b, bits - 1);
        }
    };

    gray_path(A, B, N);
    for (int i = 0; i < (int)ans.size(); i++) {
        cout << ans[i] << " \n"[i + 1 == (int)ans.size()];
    }

    return 0;
}

