// Generate Gray code path from 'start' to 'end' within the subcube
// defined by 'mask' bits (the free bits), with 'fixed' bits fixed.
// This is complex. Let me use a simpler known method.

#include <bits/stdc++.h>
using namespace std;

/*
We need a Hamiltonian path in the N-dimensional hypercube from A to B.
Such a path exists iff A and B have different parity of popcount, i.e.
popcount(A xor B) is odd. (Hypercube is bipartite, and a Hamiltonian path
covering all 2^N vertices must start and end in different parts.)

Construction:
Let x = A xor B. If popcount(x) is odd, we recursively construct a Gray-like
ordering g over dimensions represented by mask x, from 0 to x.
Then answer is A xor g[i].

Recursive function solve(n, x) where x < 2^n and popcount(x) odd:
returns a sequence of length 2^n, a permutation of [0, 2^n), starting at 0,
ending at x, consecutive elements differ by one bit.

Recurrence:
Choose a bit p where x has 1.
Choose a bit q != p where x has 0 (possible for n>=2 unless n=1 base case).
Let y = x without bit p and also without bit q compressed to n-1 dimensions.
Build sub = solve(n-1, compress(x without p toggled appropriately)) more simply
using:
Let x' = remove bit p from x. Since popcount(x') is even, choose q in x' zero bit.
Then split using q in the (n-1)-dim space:
Take u = x' xor (1<<q), which has odd popcount.
S = solve(n-1, u), T = reverse of S xor x'
Then concatenate:
embed_q(S,0) followed by embed_q(T,1<<q)
This starts at 0 and ends at x'.

Finally reinsert bit p:
Let z = x without bit p compressed => x'
Build seq' from 0 to x' in n-1 dims.
Then answer in n dims:
first half: insert bit p = 0 for seq'
second half: insert bit p = 1 for reversed(seq') xor x'
This ends at x and adjacency holds.

A simpler standard recursion is implemented below.
*/

vector<int> build(int n, int x) {
    if (n == 1) {
        return {0, 1}; // x must be 1
    }

    int p = __builtin_ctz(x); // bit set in x

    // Remove bit p from x to get y in n-1 dimensions
    int y = 0;
    for (int i = 0, j = 0; i < n; ++i) {
        if (i == p) continue;
        if (x >> i & 1) y |= (1 << j);
        ++j;
    }

    // popcount(y) is even. Choose a zero bit q in y.
    int q = -1;
    for (int i = 0; i < n - 1; ++i) {
        if (((y >> i) & 1) == 0) {
            q = i;
            break;
        }
    }

    int u = y ^ (1 << q); // odd popcount
    vector<int> s = build(n - 1, u);

    vector<int> t(s.size());
    for (int i = 0; i < (int)s.size(); ++i) {
        t[i] = s[(int)s.size() - 1 - i] ^ y;
    }

    // concat a = embed q-bit 0 into s, b = embed q-bit 1 into t
    vector<int> seq2;
    seq2.reserve(1 << (n - 1));
    auto embed = [&](int v, int bit) {
        int res = 0;
        for (int i = 0, j = 0; i < n - 1; ++i) {
            if (i == q) {
                if (bit) res |= (1 << i);
            } else {
                if (v >> j & 1) res |= (1 << i);
                ++j;
            }
        }
        return res;
    };

    for (int v : s) seq2.push_back(embed(v, 0));
    for (int v : t) seq2.push_back(embed(v, 1));

    // seq2 is in n-1 dims, from 0 to y.
    // Reinsert bit p using standard doubling to end at x.
    vector<int> ans;
    ans.reserve(1 << n);

    auto insertp = [&](int v, int bit) {
        int res = 0;
        for (int i = 0, j = 0; i < n; ++i) {
            if (i == p) {
                if (bit) res |= (1 << i);
            } else {
                if (v >> j & 1) res |= (1 << i);
                ++j;
            }
        }
        return res;
    };

    for (int v : seq2) ans.push_back(insertp(v, 0));
    for (int i = (int)seq2.size() - 1; i >= 0; --i) ans.push_back(insertp(seq2[i] ^ y, 1));

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B;
    cin >> N >> A >> B;

    int x = A ^ B;
    if ((__builtin_popcount((unsigned)x) & 1) == 0) {
        cout << "NO\n";
        return 0;
    }

    vector<int> seq = build(N, x);
    for (int &v : seq) v ^= A;

    cout << "YES\n";
    for (int i = 0; i < (int)seq.size(); ++i) {
        if (i) cout << ' ';
        cout << seq[i];
    }
    cout << '\n';
    return 0;
}

