    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int A = sc.nextInt();
        int B = sc.nextInt();
        sc.close();

        int dist = Integer.bitCount(A ^ B);
        if (dist % 2 == 0) {
            System.out.println("NO");
            return;
        }

        List<Integer> path = new ArrayList<>();
        buildGrayPath(N, A, B, path);
        System.out.println("YES");
        for (int i = 0; i < path.size(); i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(path.get(i));
        }
        System.out.println();
    }

    static void buildGrayPath(int n, int a, int b, List<Integer> path) {
        if (n == 1) {
            path.add(a);
            path.add(b);
            return;
        }
        int mask = 1 << (n - 1);
        if ((a & mask) == (b & mask)) {
            // Same highest bit
            buildGrayPath(n - 1, a & (mask - 1), b & (mask - 1), path);
            // Now we have path from low bits of a to low bits of b.
            // We need to insert the high bits properly.
            int highBit = a & mask;
            int size = path.size();
            for (int i = 0; i < size; i++) {
                path.set(i, path.get(i) | highBit);
            }
            // Mirror and flip high bit for the other half
            int halfSize = 1 << (n - 1);
            for (int i = halfSize - 1; i >= 0; i--) {
                path.add((path.get(i) & (mask - 1)) | (highBit ^ mask));
            }
        } else {
            // Different highest bits
            // Pick a midpoint that shares high bit with a and low bits can connect
            int midLow = a & (mask - 1);
            int mid = (a & mask) | midLow;
            buildGrayPath(n - 1, a & (mask - 1), midLow, path);
            int size = path.size();
            for (int i = 0; i < size; i++) {
                path.set(i, path.get(i) | (a & mask));
            }
            int halfSize = 1 << (n - 1);
            for (int i = halfSize - 1; i >= 0; i--) {
                path.add((path.get(i) & (mask - 1)) | (b & mask));
            }
        }
    }
}

