        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), A = sc.nextInt(), B = sc.nextInt();
        int xorAB = A ^ B;
        if (Integer.bitCount(xorAB) % 2 == 0) {
            System.out.println("NO");
            return;
        }
        // Find a bit where A and B differ
        int k = Integer.numberOfTrailingZeros(xorAB);
        // Generate standard Gray code, swap bit k with bit N-1, XOR with A
        int size = 1 << N;
        int[] perm = new int[size];
        for (int i = 0; i < size; i++) {
            int g = i ^ (i >> 1); // standard gray code
            // swap bit k and bit N-1
            int bk = (g >> k) & 1, bn = (g >> (N-1)) & 1;
            g = g & ~(1 << k) & ~(1 << (N-1));
            g |= (bk << (N-1)) | (bn << k);
            perm[i] = g ^ A;
        }
        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < size; i++) {
            if (i > 0) sb.append(' ');
            sb.append(perm[i]);
        }
        System.out.println(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static List<Integer> build(int n, int a, int b) {
        if (n == 1) {
            List<Integer> res = new ArrayList<>();
            res.add(a);
            res.add(b);
            return res;
        }

        int bit = Integer.numberOfTrailingZeros(a ^ b); // a and b differ here
        int mask = 1 << bit;

        int c = a ^ 1; // differs from a by one bit
        if (c == b) c = a ^ 2; // avoid b; possible since n >= 2

        int a0 = removeBit(a, bit);
        int c0 = removeBit(c, bit);
        int c1 = removeBit(c ^ mask, bit);
        int b1 = removeBit(b, bit);

        List<Integer> left = build(n - 1, a0, c0);
        List<Integer> right = build(n - 1, c1, b1);

        List<Integer> res = new ArrayList<>(1 << n);
        for (int x : left) res.add(insertBit(x, bit, 0));
        for (int x : right) res.add(insertBit(x, bit, 1));
        return res;
    }

    static int removeBit(int x, int bit) {
        int low = x & ((1 << bit) - 1);
        int high = x >> (bit + 1);
        return low | (high << bit);
    }

    static int insertBit(int x, int bit, int val) {
        int low = x & ((1 << bit) - 1);
        int high = x >> bit;
        return low | (val << bit) | (high << (bit + 1));
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();

        // In an n-dimensional hypercube, a Hamiltonian path between A and B
        // exists iff A and B are in different bipartite classes,
        // i.e. popcount(A) parity != popcount(B) parity,
        // equivalently popcount(A ^ B) is odd.
        if ((Integer.bitCount(A ^ B) & 1) == 0) {
            System.out.println("NO");
            return;
        }

        List<Integer> ans = build(N, A, B);

        StringBuilder sb = new StringBuilder();
        sb.append("YES\n");
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans.get(i));
        }
        sb.append('\n');
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
